class ExactStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
                        for ticker in tickers}

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.spy_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.aapl_rsi_previous_close = None
        self.aapl_rsi_gains = []
        self.aapl_rsi_average_gain = None
        self.aapl_rsi_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = {}
        for symbol in self.symbols.values():
            if symbol not in data.Bars:
                continue
            bars[symbol] = data.Bars[symbol]

        self._update_market_state(bars)

        if len(bars) != len(self.symbols):
            return

        if self.spy_sma is None or self.spy_previous_sma is None:
            strategy_a_buy = False
            strategy_a_sell = False
        else:
            strategy_a_buy = (
                self.spy_previous_close <= self.spy_previous_sma
                and bars[self.spy].Close > self.spy_sma
            )
            strategy_a_sell = (
                self.spy_previous_close >= self.spy_previous_sma
                and bars[self.spy].Close < self.spy_sma
            )

        strategy_b_buy = self.aapl_red_streak >= 3
        strategy_b_sell = self.aapl_rsi is not None and self.aapl_rsi > 60

        # Evaluate all sells before any buys.
        if self.strategy_a_shares > 0 and strategy_a_sell:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and strategy_b_sell:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and strategy_a_buy:
            target_value = 0.40 * self.Portfolio.TotalPortfolioValue
            shares = int(target_value / bars[self.spy].Close)
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and strategy_b_buy:
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 / bars[self.aapl].Close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

    def _update_market_state(self, bars):
        if self.spy in bars:
            close = bars[self.spy].Close

            previous_sma = self.spy_sma
            self.spy_closes.append(close)

            if len(self.spy_closes) == 100:
                self.spy_sma = sum(self.spy_closes) / 100.0
            else:
                self.spy_sma = None

            self.spy_previous_sma = previous_sma
            self.spy_previous_close = close

        if self.aapl in bars:
            close = bars[self.aapl].Close

            if self.aapl_previous_close is not None:
                if close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                elif close > self.aapl_previous_close:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = close

            if self.aapl_rsi_previous_close is not None:
                change = close - self.aapl_rsi_previous_close
                gain = max(change, 0)
                loss = max(-change, 0)

                if self.aapl_rsi_average_gain is None:
                    self.aapl_rsi_gains.append((gain, loss))

                    if len(self.aapl_rsi_gains) == 14:
                        self.aapl_rsi_average_gain = (
                            sum(item[0] for item in self.aapl_rsi_gains) / 14.0
                        )
                        self.aapl_rsi_average_loss = (
                            sum(item[1] for item in self.aapl_rsi_gains) / 14.0
                        )
                        self.aapl_rsi = self._calculate_rsi(
                            self.aapl_rsi_average_gain,
                            self.aapl_rsi_average_loss
                        )
                else:
                    self.aapl_rsi_average_gain = (
                        (self.aapl_rsi_average_gain * 13.0) + gain
                    ) / 14.0
                    self.aapl_rsi_average_loss = (
                        (self.aapl_rsi_average_loss * 13.0) + loss
                    ) / 14.0
                    self.aapl_rsi = self._calculate_rsi(
                        self.aapl_rsi_average_gain,
                        self.aapl_rsi_average_loss
                    )

            self.aapl_rsi_previous_close = close

    def _calculate_rsi(self, average_gain, average_loss):
        if average_loss == 0:
            return 100.0
        relative_strength = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))
