        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.spy_closes = RollingWindow[float](100)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        present = {}

        for symbol in self.symbols:
            if not data.Bars.ContainsKey(symbol):
                continue

            present[symbol] = data.Bars[symbol]

        for symbol, bar in present.items():
            if symbol == self.spy:
                self.spy_sma.Update(bar.EndTime, bar.Close)
                self.spy_closes.Add(float(bar.Close))

            elif symbol == self.aapl:
                self.aapl_rsi.Update(bar.EndTime, bar.Close)

                if self.aapl_previous_close is not None:
                    if bar.Close < self.aapl_previous_close:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0

                self.aapl_previous_close = float(bar.Close)

        if self.spy in present and self.spy_sma.IsReady:
            current_spy_close = float(present[self.spy].Close)
            current_spy_sma = float(self.spy_sma.Current.Value)

            if not self.IsWarmingUp:
                self.EvaluateStrategyASell(
                    current_spy_close,
                    current_spy_sma
                )

                if self.strategy_a_lot == 0:
                    self.EvaluateStrategyABuy(
                        current_spy_close,
                        current_spy_sma
                    )

            self.previous_spy_close = current_spy_close
            self.previous_spy_sma = current_spy_sma

        if self.aapl in present and self.aapl_rsi.IsReady and not self.IsWarmingUp:
            self.EvaluateStrategyBSell()

            if self.strategy_b_lot == 0:
                self.EvaluateStrategyBBuy()

    def EvaluateStrategyASell(self, close, sma):
        if self.strategy_a_lot <= 0:
            return

        if (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and close < sma
        ):
            self.MarketOrder(
                self.spy,
                -self.strategy_a_lot,
                tag="Strategy A Sell"
            )

    def EvaluateStrategyABuy(self, close, sma):
        if (
            self.previous_spy_close is None
            or self.previous_spy_sma is None
        ):
            return

        if (
            self.previous_spy_close <= self.previous_spy_sma
            and close > sma
        ):
            target_value = 0.40 * self.Portfolio.TotalPortfolioValue
            quantity = int(target_value / close)

            if quantity > 0:
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A Buy"
                )

    def EvaluateStrategyBSell(self):
        if self.strategy_b_lot <= 0:
            return

        if self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(
                self.aapl,
                -self.strategy_b_lot,
                tag="Strategy B Sell"
            )

    def EvaluateStrategyBBuy(self):
        if self.aapl_red_streak >= 3:
            available_cash = self.Portfolio.Cash
            if available_cash >= 20000:
                quantity = int(20000 / self.Securities[self.aapl].Price)

                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B Buy"
                    )

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Status != OrderStatus.Filled:
            return

        order = self.Transactions.GetOrderById(orderEvent.OrderId)
        fill_quantity = int(orderEvent.FillQuantity)

        if order.Tag == "Strategy A Buy":
            self.strategy_a_lot += fill_quantity
        elif order.Tag == "Strategy A Sell":
            self.strategy_a_lot += fill_quantity
        elif order.Tag == "Strategy B Buy":
            self.strategy_b_lot += fill_quantity
        elif order.Tag == "Strategy B Sell":
            self.strategy_b_lot += fill_quantity
