class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.current_slot = 0  # 0 = Strategy A, 1 = Strategy B

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = {}

        for symbol in self.symbols.values():
            if not data.Bars.ContainsKey(symbol):
                continue
            bars[symbol] = data.Bars[symbol]

        if self.spy in bars:
            spy_bar = bars[self.spy]
            self.spy_sma.Update(
                IndicatorDataPoint(spy_bar.EndTime, spy_bar.Close)
            )

            if self.spy_previous_close is not None:
                pass

        if self.aapl in bars:
            aapl_bar = bars[self.aapl]
            self.aapl_rsi.Update(
                IndicatorDataPoint(aapl_bar.EndTime, aapl_bar.Close)
            )

            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_bar.Close

        if self.spy in bars and self.spy_sma.IsReady:
            self.spy_previous_close = bars[self.spy].Close
            self.spy_previous_sma = self.spy_sma.Current.Value

        if self.IsWarmingUp:
            return

        if len(bars) != len(self.symbols):
            return

        if (
            not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
            or self.spy_previous_close is None
            or self.spy_previous_sma is None
            or self.aapl_previous_close is None
        ):
            return

        spy_bar = bars[self.spy]
        current_spy_close = spy_bar.Close
        current_spy_sma = self.spy_sma.Current.Value

        aapl_bar = bars[self.aapl]
        current_aapl_rsi = self.aapl_rsi.Current.Value

        # The previous values were captured after today's indicator update.
        # Maintain explicit prior-day values for cross detection.
        previous_spy_close = getattr(self, "_cross_previous_spy_close", None)
        previous_spy_sma = getattr(self, "_cross_previous_spy_sma", None)

        if previous_spy_close is None or previous_spy_sma is None:
            self._cross_previous_spy_close = current_spy_close
            self._cross_previous_spy_sma = current_spy_sma
            return

        if self.current_slot == 0:
            # Sell Strategy A before evaluating its buy reason.
            if self.strategy_a_lot > 0:
                crosses_below = (
                    previous_spy_close <= previous_spy_sma
                    and current_spy_close < current_spy_sma
                )

                if crosses_below:
                    self.MarketOrder(
                        self.spy,
                        -self.strategy_a_lot,
                        tag="Strategy A sell"
                    )
                    self.strategy_a_lot = 0
                    self.current_slot = 1

            # Strategy A buy.
            if self.current_slot == 0 and self.strategy_a_lot == 0:
                crosses_above = (
                    previous_spy_close <= previous_spy_sma
                    and current_spy_close > current_spy_sma
                )

                if crosses_above:
                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    quantity = int(target_value / current_spy_close)

                    if quantity > 0:
                        self.MarketOrder(
                            self.spy,
                            quantity,
                            tag="Strategy A buy"
                        )
                        self.strategy_a_lot = quantity

        if self.current_slot == 1:
            # Sell Strategy B before evaluating its buy reason.
            if self.strategy_b_lot > 0:
                if current_aapl_rsi > 60:
                    self.MarketOrder(
                        self.aapl,
                        -self.strategy_b_lot,
                        tag="Strategy B sell"
                    )
                    self.strategy_b_lot = 0
                    self.current_slot = 0

            # Strategy B buy.
            if self.current_slot == 1 and self.strategy_b_lot == 0:
                if self.aapl_red_streak >= 3:
                    if self.Portfolio.Cash >= 20000:
                        quantity = int(20000 / aapl_bar.Close)

                        if quantity > 0:
                            self.MarketOrder(
                                self.aapl,
                                quantity,
                                tag="Strategy B buy"
                            )
                            self.strategy_b_lot = quantity

        self._cross_previous_spy_close = current_spy_close
        self._cross_previous_spy_sma = current_spy_sma
